<?php
/** Settings fields shared by the active tab and Setup Wizard. */
namespace CHADA_AIO;
defined('ABSPATH') || exit;

/** @var list<array<string, mixed>> $chada_aio_fields Settings field definitions. */
assert(isset($chada_aio_fields));
?><div class="chada-settings-fields">
    <?php foreach ($chada_aio_fields as $chada_aio_field): ?>
        <?php $chada_aio_field_key = (string) ($chada_aio_field['key'] ?? ''); $chada_aio_field_type = (string) ($chada_aio_field['type'] ?? 'text'); $chada_aio_field_value = $chada_aio_field['value'] ?? ''; $chada_aio_placeholder = (string) ($chada_aio_field['placeholder'] ?? ''); $chada_aio_required = !empty($chada_aio_field['required']); $chada_aio_readonly = !empty($chada_aio_field['readonly']); $chada_aio_description = (string) ($chada_aio_field['description'] ?? ''); $chada_aio_guidance = is_array($chada_aio_field['guidance'] ?? null) ? $chada_aio_field['guidance'] : []; $chada_aio_field_id = 'chada-setting-' . preg_replace('/[^a-z0-9_-]+/i', '-', $chada_aio_field_key); $chada_aio_help_id = $chada_aio_field_id . '-help'; $chada_aio_has_help = $chada_aio_description !== '' || $chada_aio_guidance !== []; ?>
        <label><span><?php echo esc_html((string) ($chada_aio_field['label'] ?? '')); ?><?php if ($chada_aio_required): ?><span class="chada-required" aria-hidden="true">*</span><span class="screen-reader-text"> <?php esc_html_e('Required field', 'chada-aio'); ?></span><?php endif; ?></span>
            <?php if ($chada_aio_field_type === 'select'): ?><select id="<?php echo esc_attr($chada_aio_field_id); ?>" name="<?php echo esc_attr($chada_aio_field_key); ?>"<?php echo $chada_aio_required ? ' required' : ''; ?><?php if ($chada_aio_has_help): ?> aria-describedby="<?php echo esc_attr($chada_aio_help_id); ?>"<?php endif; ?>><?php foreach ($chada_aio_field['options'] ?? [] as $chada_aio_option): ?><option value="<?php echo esc_attr((string) ($chada_aio_option['value'] ?? '')); ?>" <?php selected($chada_aio_field_value, $chada_aio_option['value'] ?? '', true); ?>><?php echo esc_html((string) ($chada_aio_option['label'] ?? '')); ?></option><?php endforeach; ?></select>
            <?php elseif ($chada_aio_field_type === 'textarea'): ?><textarea id="<?php echo esc_attr($chada_aio_field_id); ?>" name="<?php echo esc_attr($chada_aio_field_key); ?>" rows="<?php echo esc_attr((string) ($chada_aio_field['rows'] ?? 3)); ?>"<?php echo $chada_aio_required ? ' required' : ''; ?><?php if ($chada_aio_has_help): ?> aria-describedby="<?php echo esc_attr($chada_aio_help_id); ?>"<?php endif; ?>><?php echo esc_textarea((string) $chada_aio_field_value); ?></textarea>
            <?php elseif ($chada_aio_field_type === 'checkbox'): ?><input id="<?php echo esc_attr($chada_aio_field_id); ?>" type="checkbox" name="<?php echo esc_attr($chada_aio_field_key); ?>" <?php checked($chada_aio_field_value, true); ?><?php if ($chada_aio_has_help): ?> aria-describedby="<?php echo esc_attr($chada_aio_help_id); ?>"<?php endif; ?>>
            <?php else: ?><input id="<?php echo esc_attr($chada_aio_field_id); ?>" type="<?php echo esc_attr($chada_aio_field_type); ?>" name="<?php echo esc_attr($chada_aio_field_key); ?>" value="<?php echo esc_attr((string) $chada_aio_field_value); ?>"<?php if ($chada_aio_placeholder !== ''): ?> placeholder="<?php echo esc_attr($chada_aio_placeholder); ?>"<?php endif; ?><?php echo $chada_aio_required ? ' required' : ''; ?><?php if (isset($chada_aio_field['min'])): ?> min="<?php echo esc_attr((string) $chada_aio_field['min']); ?>"<?php endif; ?><?php if (isset($chada_aio_field['max'])): ?> max="<?php echo esc_attr((string) $chada_aio_field['max']); ?>"<?php endif; ?><?php echo $chada_aio_readonly ? ' readonly aria-readonly="true"' : ''; ?><?php if ($chada_aio_has_help): ?> aria-describedby="<?php echo esc_attr($chada_aio_help_id); ?>"<?php endif; ?>>
            <?php endif; ?>
            <?php if ($chada_aio_has_help): ?><span id="<?php echo esc_attr($chada_aio_help_id); ?>" class="description"><?php if ($chada_aio_description !== ''): ?><span><?php echo esc_html($chada_aio_description); ?></span><?php endif; ?><?php if ($chada_aio_guidance !== []): ?><span class="chada-path-guidance"><span><?php esc_html_e('Host filesystem root:', 'chada-aio'); ?> <code><?php echo esc_html((string) ($chada_aio_guidance['filesystem_root'] ?? '')); ?></code></span><span><?php esc_html_e('Example private storage path:', 'chada-aio'); ?> <code><?php echo esc_html((string) ($chada_aio_guidance['example'] ?? '')); ?></code></span><span><?php echo esc_html((string) ($chada_aio_guidance['blank_note'] ?? '')); ?></span><?php if (($chada_aio_guidance['constant_note'] ?? '') !== ''): ?><span><?php echo esc_html((string) $chada_aio_guidance['constant_note']); ?></span><?php endif; ?></span><?php endif; ?></span><?php endif; ?>
        </label>
    <?php endforeach; ?>
</div>
